import json,random,math,re,statistics,pathlib
R=random.Random(20271101)
O=pathlib.Path(__file__).resolve().parents[1]/'data'/'questions.json'
Q=[]
subjects={'Português':'Português','Matemática':'Raciocínio Lógico-Matemático','Direito':'Direito e Direitos Humanos','Inglês':'Inglês','Literatura':'Literatura'}

def add(s,topic,stem,correct,wrong,why,extra=None):
    wrong=list(dict.fromkeys([str(x) for x in wrong if str(x)!=str(correct)]))
    if len(wrong)<3: raise ValueError((s,stem,correct,wrong))
    opts=[str(correct),*R.sample(wrong,3)];R.shuffle(opts)
    q={'id':f'FP-{len(Q)+1:04d}','subject':subjects[s],'topic':topic,'origin':'autoral','sourceLabel':'Autoral · Foco PMMG 2027','year':2026,'stem':str(stem),'options':opts,'answer':opts.index(str(correct)),'explanation':str(why),'difficulty':['Fácil','Média','Difícil'][len(Q)%3],'reviewStatus':'revisao_editorial'}
    if extra:q.update(extra)
    Q.append(q)

