for topic,question,rights,wrongs,exp in pt:
    for i in range(4):
        a=rights[i];b=wrongs[i]
        if '|' in a:
            example,good=a.split('|',1);bad=b.split('|',1)[1]
            add('Português',topic,f'{question}\n\n{example}',good,[bad,'Nenhuma das alternativas','Todas as classificações possíveis'],exp)
        else:
            add('Português',topic,question, a,[b,*[wrongs[j] for j in range(4) if j!=i][:2]],exp)
# 100 English - 25 contexts x 4 types
english=[
('Present simple','She ___ to work every day.','goes','go,going,gone'),('Present continuous','They ___ studying now.','are','is,am,be'),('Past simple','Yesterday, he ___ early.','arrived','arrive,arrives,arriving'),('Future','Tomorrow, we ___ review the lesson.','will','were,did,has'),('Modal verbs','You ___ wear a seat belt.','must','must to,has,are'),('Comparatives','This test is ___ than the last one.','easier','easy,easiest,more easy'),('Superlatives','She is the ___ student in class.','best','better,good,well'),('Prepositions','The class starts ___ eight o’clock.','at','in,on,for'),('Articles','He is ___ honest person.','an','a,the,none'),('Pronouns','This book belongs to Ana. It is ___.','hers','her,she,herself'),('Conditionals','If it rains, we ___ stay home.','will','would have,had,were'),('Passive voice','The document ___ signed yesterday.','was','were,is,has'),('Present perfect','I have ___ this book before.','read','reads,reading,reed'),('Quantifiers','How ___ students are here?','many','much,little,a little'),('Question forms','___ do you live?','Where','Who,When,Whose'),('Negation','He ___ like coffee.','does not','do not,is not,has not'),('Connectors','It was raining; ___, we continued.','however','because,therefore,since'),('Possessives','That is ___ car.','my','mine,me,I'),('There is/are','There ___ three books on the desk.','are','is,am,be'),('Adverbs','She speaks English ___.','fluently','fluent,fluency,more fluent'),('Gerunds','He enjoys ___ at night.','reading','read,to read,reads'),('Infinitives','They decided ___ early.','to leave','leaving,leave,left'),('Relative clauses','The person ___ called is my friend.','who','where,when,whose'),('Vocabulary','The opposite of “safe” is ___.','dangerous','secure,protected,harmless'),('Vocabulary','The closest meaning of “rapid” is ___.','fast','slow,late,weak'),
]
for i,(topic,sentence,right,wrong) in enumerate(english):
    for j in range(4):
        prompts=[f'Choose the best option to complete the sentence:\n\n“{sentence}”',f'Choose the grammatically correct option:\n\n“{sentence}”',f'Complete the sentence in standard English:\n\n“{sentence}”',f'Identify the word that best fits the context:\n\n“{sentence}”']
        # Variation for repeated grammar concept: change context through consistent exact substitutions only
        variants=[sentence,sentence.replace('every day','each morning').replace('now','at this moment').replace('yesterday','last week').replace('Tomorrow','Next week').replace('early','on time'),sentence.replace('work','school').replace('class','group').replace('book','article').replace('coffee','tea').replace('car','house'),sentence.replace('She ','Maria ').replace('he ','the applicant ').replace('He ','The applicant ').replace('They ','The students ').replace('we ','the team ')]
        add('Inglês',topic,prompts[j].replace(sentence,variants[j]),right,wrong.split(','),f'Em inglês, a alternativa “{right}” completa a estrutura proposta. Verifique concordância, sentido e tempo verbal no contexto.')
# 100 Mathematics: 10 x 10 parameterized deterministic.
for k in range(10):
    a=30+7*k;p=10+5*(k%6);corr=a*(100+p)//100 if a*(100+p)%100==0 else a*(100+p)/100
    add('Matemática','Porcentagem',f'Uma mensalidade custava R$ {a},00 e sofreu aumento de {p}%. Qual é o novo valor, em reais?',f'{corr:g}',[f'{a*(100-p)/100:g}',f'{a+p:g}',f'{a*(p/100):g}'],f'Valor após o reajuste: {a} × (1 + {p}/100) = R$ {corr:g}.')
    x=12+k*3;y=6+k
    add('Matemática','Razões e proporções',f'Uma viatura percorre {x} km em {y} minutos, em velocidade constante. Quantos quilômetros percorrerá em {y*3} minutos?',str(x*3),[str(x*2),str(x+y),str(x*4)],f'Pela proporcionalidade direta, o tempo triplica e a distância também: {x} × 3 = {x*3}.')
    n=6+k; seq=list(range(2,2*n+1,2));ans=sum(seq)/len(seq)
    add('Matemática','Média aritmética',f'Qual é a média aritmética dos números pares de 2 até {2*n}, inclusive?',f'{ans:g}',[f'{ans+1:g}',f'{ans-1:g}',f'{2*n:g}'],f'A soma dos extremos é {2+2*n}; a média da progressão é (2 + {2*n})/2 = {ans:g}.')
    b=7+k;h=4+k;ans=b*h
    add('Matemática','Geometria plana',f'Qual é a área de um retângulo com {b} m de base e {h} m de altura?',str(ans),[str(2*(b+h)),str(ans//2),str(ans+b)],f'Área do retângulo = base × altura = {b} × {h} = {ans} m².')
    c=3+k;d=4+k;ans=c*d
    add('Matemática','Probabilidade',f'Uma caixa contém {c} bolas azuis e {d} vermelhas. Retira-se uma bola ao acaso. Qual é a probabilidade de ela ser azul?',f'{c}/{c+d}',[f'{d}/{c+d}',f'{c}/{d}',f'{c+d}/{c}'],f'Casos favoráveis: {c}. Total: {c+d}. Probabilidade: {c}/{c+d}.')
    t=2+k;add('Matemática','Equação do 1º grau',f'Qual é o valor de x na equação 3x + {3*t} = {3*t+21}?','7',['5','8','10'],f'Subtraindo {3*t}, fica 3x = 21; logo x = 7.')
    logic_cases=[(True,False,'P e Q',False),(True,False,'P ou Q',True),(True,False,'P implica Q',False),(True,False,'P se, e somente se, Q',False),(False,False,'P e Q',False),(False,True,'P ou Q',True),(False,True,'P implica Q',True),(False,True,'P se, e somente se, Q',False),(True,True,'P e Q',True),(True,True,'P se, e somente se, Q',True)]
    pv,qv,expr,truth=logic_cases[k]
    add('Matemática','Lógica proposicional',f'Considere P {"verdadeira" if pv else "falsa"} e Q {"verdadeira" if qv else "falsa"}. Qual o valor lógico de “{expr}”?','Verdadeiro' if truth else 'Falso',['Falso' if truth else 'Verdadeiro','Indeterminado','Depende da ordem'], f'P={pv}, Q={qv}. Pela tabela-verdade do conectivo “{expr}”, o resultado é {"verdadeiro" if truth else "falso"}.')
    r=2+k;add('Matemática','Princípio multiplicativo',f'Uma senha é formada por um símbolo escolhido entre {r+2} possibilidades e um algarismo escolhido entre 10 possibilidades. Quantas senhas distintas são possíveis?',str((r+2)*10),[str(r+13),str((r+2)+10),str((r+2)*9)],f'Pelo princípio multiplicativo: {r+2} × 10 = {(r+2)*10}.')
    z=2+k;add('Matemática','Sequências',f'Na progressão aritmética {z}, {z+4}, {z+8}, ... qual é o 8º termo?',str(z+28),[str(z+24),str(z+32),str(z+8)],f'a₈ = a₁ + 7r = {z} + 7×4 = {z+28}.')
    count=80+10*k; sample=20+2*k
    add('Matemática','Estatística',f'Em uma população de {count} candidatos, {sample} foram entrevistados. O conjunto dos {sample} entrevistados é chamado de:', 'amostra',['população','variável','frequência relativa'], 'Amostra é a parcela da população selecionada para observação.')
