# 100 direito: 50 proposicoes de Direito Constitucional, DUDH, LINDB and CADH x 2 question formulations.
law=[
('CF/88 — Fundamentos','A dignidade da pessoa humana é fundamento da República Federativa do Brasil.','A União tem como fundamento a supremacia do Poder Executivo.','A Constituição exclui a dignidade dos fundamentos republicanos.','O Brasil adota o partido único como fundamento estatal.'),
('CF/88 — Poderes','Legislativo, Executivo e Judiciário são Poderes da União, independentes e harmônicos entre si.','A União possui apenas dois poderes.','O Executivo é hierarquicamente superior ao Judiciário.','O Legislativo pode extinguir a independência do Judiciário.'),
('CF/88 — Objetivos','Construir uma sociedade livre, justa e solidária é objetivo fundamental da República.','Abolir os direitos fundamentais é objetivo da República.','Extinguir o pluralismo é objetivo da República.','Suprimir a cidadania é objetivo da República.'),
('CF/88 — Objetivos','Erradicar a pobreza e a marginalização é objetivo fundamental da República.','Manter desigualdades regionais é objetivo expresso.','Reduzir liberdades civis é objetivo expresso.','Estabelecer uma religião oficial é objetivo expresso.'),
('CF/88 — Relações internacionais','A prevalência dos direitos humanos orienta as relações internacionais do Brasil.','O racismo orienta as relações internacionais do Brasil.','A intervenção arbitrária é princípio constitucional expresso.','O expansionismo territorial é princípio constitucional expresso.'),
('CF/88 — Igualdade','Todos são iguais perante a lei, sem distinção de qualquer natureza, nos termos da Constituição.','A igualdade só se aplica a servidores públicos.','A Constituição não trata de igualdade.','A igualdade não alcança direitos individuais.'),
('CF/88 — Legalidade','Ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei.','Qualquer autoridade pode criar obrigações sem base legal.','A obrigação de cumprir a lei depende sempre de contrato.','A legalidade é aplicável somente ao direito privado.'),
('CF/88 — Tortura','Ninguém será submetido a tortura nem a tratamento desumano ou degradante.','A tortura é admitida em qualquer investigação.','A Constituição permite tortura administrativa.','Tratamento degradante é sempre obrigatório.'),
('CF/88 — Liberdade de consciência','É inviolável a liberdade de consciência e de crença, nos termos constitucionais.','A Constituição proíbe toda manifestação religiosa.','A liberdade de crença é restrita ao Poder Executivo.','A proteção da crença depende de autorização policial.'),
('CF/88 — Manifestação do pensamento','É livre a manifestação do pensamento, sendo vedado o anonimato.','A Constituição permite anonimato irrestrito como regra expressa.','Toda crítica é proibida constitucionalmente.','A liberdade de manifestação só existe em período eleitoral.'),
('CF/88 — Privacidade','São invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, observada a Constituição.','A vida privada não recebe proteção constitucional.','A honra é protegida apenas de militares.','A imagem não é direito protegido.'),
('CF/88 — Domicílio','A casa é asilo inviolável do indivíduo, com exceções constitucionais.','A polícia pode ingressar em qualquer domicílio a qualquer momento sem exceções ou requisitos.','Domicílio não possui proteção constitucional.','A inviolabilidade não admite nenhuma exceção constitucional.'),
('CF/88 — Reunião','É livre a reunião pacífica, sem armas, em locais abertos ao público, atendidos os requisitos constitucionais.','Toda reunião depende sempre de autorização prévia.','A reunião armada possui proteção irrestrita.','Reunião pacífica é proibida em todo local público.'),
('CF/88 — Associação','É plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar.','São permitidas associações paramilitares sem restrições.','É obrigatória a associação de todos os cidadãos.','Associações lícitas são proibidas constitucionalmente.'),
('CF/88 — Propriedade','É garantido o direito de propriedade, nos termos da Constituição.','A Constituição não reconhece propriedade privada.','Todo imóvel privado é automaticamente público.','O direito de propriedade não possui qualquer previsão constitucional.'),
('CF/88 — Função social','A propriedade atenderá a sua função social.','A propriedade jamais está sujeita a função social.','A função social é conceito ausente da Constituição.','A Constituição dispensa toda propriedade de qualquer limite.'),
('CF/88 — Direito de petição','O direito de petição aos poderes públicos é assegurado independentemente do pagamento de taxas, nas hipóteses constitucionais.','Peticionar exige sempre taxa federal.','Somente autoridades públicas podem peticionar.','O direito de petição está proibido.'),
('CF/88 — Acesso à Justiça','A lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito.','O Judiciário é proibido de apreciar ameaça a direito.','O acesso à Justiça depende de autorização policial.','Lesão a direito nunca pode ser judicializada.'),
('CF/88 — Devido processo legal','Ninguém será privado da liberdade ou de seus bens sem o devido processo legal.','O devido processo só existe em processos privados.','O devido processo é incompatível com a Constituição.','Toda privação de bens dispensa procedimento.'),
('CF/88 — Contraditório','São assegurados o contraditório e a ampla defesa aos litigantes e aos acusados em geral, nos termos constitucionais.','O contraditório é proibido em processos administrativos.','A ampla defesa não existe em matéria constitucional.','Todo acusado deve ser impedido de se defender.'),
('CF/88 — Presunção de inocência','Ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória.','A simples suspeita equivale a condenação definitiva.','A presunção constitucional é sempre de culpa.','Sentença penal condenatória nunca tem trânsito em julgado.'),
('CF/88 — Habeas corpus','O habeas corpus protege a liberdade de locomoção diante de violência ou coação ilegal, nos termos constitucionais.','Habeas corpus serve exclusivamente para cobrar impostos.','Habeas corpus elimina toda lei penal.','Habeas corpus é um contrato de compra e venda.'),
('CF/88 — Mandado de segurança','O mandado de segurança protege direito líquido e certo nas condições constitucionais.','Mandado de segurança é modalidade de prisão.','Mandado de segurança serve para dissolver partidos sem processo.','Mandado de segurança substitui todas as ações judiciais de forma irrestrita.'),
('CF/88 — Direito de greve','É assegurado o direito de greve aos trabalhadores, observadas as condições legais e constitucionais.','A Constituição proíbe toda greve de trabalhadores civis.','Greve é direito previsto somente no direito penal.','Toda greve está automaticamente livre de qualquer regra.'),
('CF/88 — Nacionalidade','A Constituição disciplina brasileiros natos e naturalizados.','A Constituição prevê apenas nacionalidade municipal.','Nacionalidade não tem disciplina constitucional.','Apenas estrangeiros podem ser brasileiros natos.'),
('CF/88 — Voto','O voto é direto e secreto, com valor igual para todos, nos termos constitucionais.','O voto deve ser sempre público e identificado.','O valor do voto varia conforme a profissão.','A Constituição proíbe eleições.'),
('CF/88 — Direitos políticos','O alistamento eleitoral e o voto são facultativos para analfabetos, nos termos constitucionais.','O voto é obrigatoriamente proibido para todos os maiores de 18 anos.','Analfabetos são necessariamente obrigados a votar.','O voto nunca pode ser facultativo.'),
('CF/88 — Administração pública','A administração pública obedece aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência.','A administração pública pode ignorar a legalidade.','A impessoalidade não é princípio constitucional.','A eficiência é proibida na administração.'),
('CF/88 — Concurso público','A investidura em cargo público depende, em regra, de aprovação prévia em concurso público, com exceções constitucionais.','Todo cargo público dispensa concurso sem exceção.','Concurso é vedado para cargos efetivos.','A Constituição proíbe concursos de provas e títulos.'),
('CF/88 — Militares estaduais','Os membros das polícias militares e dos corpos de bombeiros militares são militares dos Estados, do Distrito Federal e dos Territórios.','Policiais militares são membros do Poder Legislativo federal.','Policiais militares não têm disciplina constitucional.','Bombeiros militares integram o Poder Judiciário.'),
('CF/88 — Segurança pública','A segurança pública é dever do Estado, direito e responsabilidade de todos.','Segurança pública é direito exclusivo do Poder Executivo.','Segurança pública não é dever estatal.','Segurança pública depende exclusivamente de empresas privadas.'),
('CF/88 — PM','Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública.','À PM cabe, constitucionalmente, legislar sobre direito civil.','À PM cabe julgar causas no STF.','À PM cabe emitir moeda.'),
('CF/88 — PC','Às polícias civis incumbem, ressalvada a competência da União, funções de polícia judiciária e a apuração de infrações penais, exceto as militares.','À polícia civil cabe criar leis federais.','A polícia civil é tribunal do Poder Judiciário.','A polícia civil exerce a polícia ostensiva como atribuição constitucional exclusiva.'),
('CF/88 — Forças Armadas','As Forças Armadas são constituídas pela Marinha, pelo Exército e pela Aeronáutica.','As Forças Armadas são constituídas apenas pela Marinha.','A Polícia Civil substitui constitucionalmente o Exército.','As Forças Armadas são órgãos municipais.'),
('CF/88 — Organização do Estado','A organização político-administrativa compreende União, Estados, Distrito Federal e Municípios, todos autônomos nos termos da Constituição.','Os Municípios não participam da organização político-administrativa.','Somente a União possui autonomia.','O Brasil não possui Distrito Federal.'),
('CF/88 — Entes federativos','É vedado aos entes federativos estabelecer cultos religiosos ou igrejas, subvencioná-los ou embaraçar-lhes o funcionamento, ressalvada colaboração de interesse público na forma da lei.','A Constituição cria religião oficial obrigatória.','A União pode impor religião a todos os Estados.','O Estado não possui regras constitucionais sobre laicidade.'),
('CF/88 — Direito à vida','A inviolabilidade do direito à vida integra a proteção do art. 5º da Constituição.','A vida é direito constitucionalmente desprotegido.','O direito à vida só existe para servidores públicos.','A proteção constitucional da vida depende de filiação partidária.'),
('DUDH — Igualdade','Todos os seres humanos nascem livres e iguais em dignidade e direitos.','A DUDH afirma que dignidade depende de renda.','A DUDH proíbe a igualdade humana.','A DUDH permite escravidão universal.'),
('DUDH — Discriminação','Os direitos proclamados na Declaração aplicam-se sem distinção de raça, cor, sexo, língua, religião ou outras condições nela indicadas.','A Declaração permite discriminação por idioma.','A Declaração garante direitos apenas a nacionais.','A Declaração exclui mulheres dos direitos humanos.'),
('DUDH — Proibição da escravidão','Ninguém será mantido em escravidão ou servidão, nos termos da DUDH.','A DUDH recomenda servidão obrigatória.','A DUDH permite comércio de escravos.','A DUDH não aborda escravidão.'),
('DUDH — Proibição da tortura','Ninguém será submetido à tortura nem a tratamento ou castigo cruel, desumano ou degradante.','A DUDH exige tortura como regra.','A DUDH permite castigo cruel irrestrito.','A DUDH não contempla dignidade.'),
('DUDH — Personalidade jurídica','Todo ser humano tem direito ao reconhecimento como pessoa perante a lei.','Somente proprietários possuem personalidade jurídica na DUDH.','A DUDH exclui pobres da personalidade jurídica.','Personalidade jurídica depende de profissão.'),
('DUDH — Tribunal independente','Toda pessoa tem direito, em plena igualdade, a uma audiência justa e pública por tribunal independente e imparcial, nas condições da Declaração.','A DUDH recomenda tribunais parciais.','A DUDH proíbe audiências justas.','A DUDH exige julgamento secreto em todos os casos.'),
('DUDH — Presunção de inocência','Toda pessoa acusada de ato delituoso tem direito à presunção de inocência até que sua culpabilidade seja provada de acordo com a lei, em julgamento público com garantias de defesa.','A DUDH presume culpabilidade automática.','A DUDH proíbe defesa em julgamento.','A DUDH dispensa prova de culpabilidade.'),
('DUDH — Liberdade de pensamento','Toda pessoa tem direito à liberdade de pensamento, consciência e religião.','A DUDH impõe religião única.','A DUDH proíbe liberdade de pensamento.','Liberdade de consciência é direito exclusivo de militares.'),
('DUDH — Educação','Toda pessoa tem direito à instrução, nos termos da Declaração.','A DUDH proíbe educação básica.','Educação é direito apenas de adultos ricos.','A DUDH restringe educação a uma nacionalidade.'),
('LINDB — Vigência','Salvo disposição contrária, a lei começa a vigorar em todo o país 45 dias depois de oficialmente publicada.','Toda lei começa sempre a vigorar 100 anos depois.','Toda lei deve esperar exatamente 1 dia por imposição da LINDB.','A LINDB proíbe cláusula de vigência.'),
('LINDB — Revogação','Não se destinando à vigência temporária, a lei terá vigor até que outra a modifique ou revogue.','Lei ordinária perde validade automaticamente em sete dias.','A LINDB dispensa modificação legislativa em qualquer caso.','Toda norma é temporária por força da LINDB.'),
('CADH — Vida','A Convenção Americana sobre Direitos Humanos reconhece o direito de toda pessoa ao respeito de sua vida, nos termos do tratado.','A CADH exclui por completo a proteção à vida.','A CADH cria um dever universal de tortura.','A CADH não aborda direitos individuais.'),
('CADH — Integridade','Toda pessoa tem direito a que se respeite sua integridade física, psíquica e moral, segundo a Convenção Americana.','A integridade física é sempre irrelevante no tratado.','A CADH protege apenas a integridade patrimonial.','O tratado autoriza tortura irrestrita.')
]
assert len(law)==50,len(law)
for topic,right,*wrong in law:
    add('Direito',topic,f'Considerando {topic}, assinale a afirmação correta:',right,wrong,'Fundamento para revisão: '+topic+'. '+right,{'historicalNotice':'Conteúdo baseado no edital CFSd 2025; legislação deve ser conferida antes do lançamento.'})
    add('Direito',topic,f'Uma questão sobre {topic} exige identificar a alternativa compatível com o ordenamento jurídico. Qual é ela?',right,wrong,'A afirmação correta é: '+right,{'historicalNotice':'Conteúdo baseado no edital CFSd 2025; legislação deve ser conferida antes do lançamento.'})
# QA structure and reproducibility
counts={}
for q in Q:
    counts[q['subject']]=counts.get(q['subject'],0)+1
    assert len(q['options'])==4
    assert len(set(q['options']))==4,(q['id'],q['options'])
    assert q['options'][q['answer']]
    assert len(q['explanation'])>=20
    assert q['origin']=='autoral'
assert len(Q)==500,(len(Q),counts)
assert set(counts.values())=={100},counts
# 4 duplicated literal question stems with no distinctive example may occur: no identical stem+options
assert len({(q['stem'],tuple(sorted(q['options']))) for q in Q})==len(Q)
O.write_text(json.dumps(Q,ensure_ascii=False,indent=2),encoding='utf-8')
print('OUTPUT',O,'QUESTIONS',len(Q),'COUNTS',counts)